"""Store generated bytes once, then register the asset without calling the model again."""

import hashlib
from datetime import UTC, datetime
from uuid import UUID, uuid4

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from app.modules.generation.models import Asset, GenerationOutput, GenerationTask

_EXTENSIONS = {
    "image/png": "png",
    "image/jpeg": "jpg",
    "image/webp": "webp",
    "video/mp4": "mp4",
}


def generated_object_key(project_id: UUID, task_id: UUID, ordinal: int, extension: str) -> str:
    return f"projects/{project_id}/assets/{task_id}/{ordinal}.{extension}"


def describe_outputs(
    project_id: UUID,
    task_id: UUID,
    blobs: list[tuple[bytes, str]],
) -> list[dict]:
    items: list[dict] = []
    for ordinal, (content, mime) in enumerate(blobs, start=1):
        extension = _EXTENSIONS.get(mime)
        if extension is None:
            raise ValueError("generated media type is not supported")
        items.append(
            {
                "ordinal": ordinal,
                "object_key": generated_object_key(project_id, task_id, ordinal, extension),
                "mime": mime,
                "sha256": hashlib.sha256(content).hexdigest(),
                "size_bytes": len(content),
                "kind": "VIDEO" if mime.startswith("video/") else "IMAGE",
            }
        )
    return items


async def put_if_changed(storage, *, object_key: str, content: bytes, content_type: str) -> None:
    stat = getattr(storage, "stat_object", None)
    if stat is not None:
        size = await stat(object_key=object_key)
        if size == len(content):
            return
    last_error: Exception | None = None
    for _ in range(3):
        try:
            await storage.put_object(object_key=object_key, content=content, content_type=content_type)
            return
        except Exception as exc:
            last_error = exc
    if last_error is not None:
        raise last_error


async def remember_objects(session: AsyncSession, task_id: UUID, items: list[dict]) -> None:
    task = await _lock(session, task_id)
    if task is None or task.status != "running":
        return
    snapshot = dict(task.request_snapshot)
    snapshot["stored_objects"] = items
    task.request_snapshot = snapshot
    task.phase = "persisting"
    task.updated_at = datetime.now(UTC)
    await session.commit()


async def register_stored_assets(
    session: AsyncSession,
    task_id: UUID,
    *,
    storage_provider: str,
    bucket: str,
) -> bool:
    task = await _lock(session, task_id)
    if task is None:
        return False
    if task.status == "succeeded":
        return True
    items = task.request_snapshot.get("stored_objects") if isinstance(task.request_snapshot, dict) else None
    if not isinstance(items, list) or not items:
        return False
    existing = (
        await session.execute(select(GenerationOutput).where(GenerationOutput.task_id == task_id))
    ).scalars().all()
    if existing:
        _succeed(task)
        await session.commit()
        return True
    for item in items:
        if not isinstance(item, dict):
            continue
        asset_id = uuid4()
        session.add(
            Asset(
                id=asset_id,
                project_id=task.project_id,
                kind=item["kind"],
                object_key=item["object_key"],
                sha256=item["sha256"],
                mime=item["mime"],
                size_bytes=item["size_bytes"],
                width=None,
                height=None,
                status="ready",
                created_by=task.actor_id,
                storage_provider=storage_provider,
                bucket=bucket,
            )
        )
        session.add(
            GenerationOutput(
                project_id=task.project_id,
                task_id=task.id,
                asset_id=asset_id,
                ordinal=int(item["ordinal"]),
            )
        )
    _succeed(task)
    await session.commit()
    return True


async def _lock(session: AsyncSession, task_id: UUID) -> GenerationTask | None:
    return await session.scalar(
        select(GenerationTask).where(GenerationTask.id == task_id).with_for_update()
    )


def _succeed(task: GenerationTask) -> None:
    task.status = "succeeded"
    task.phase = None
    task.finished_at = datetime.now(UTC)
    task.updated_at = datetime.now(UTC)


def storage_identity(storage, settings) -> tuple[str, str]:
    name = getattr(storage, "provider_name", None)
    bucket = getattr(storage, "bucket_name", None)
    if isinstance(name, str) and name:
        return name, bucket if isinstance(bucket, str) else ""
    if settings.qiniu_configured:
        return "qiniu", settings.qiniu_bucket.strip()
    return "s3", settings.s3_bucket.strip()
